SELECT x.id FROM unnest($1::int[]) f(row_limit) CROSS JOIN LATERAL (SELECT id FROM probe LIMIT f.row_limit) x;
SELECT x.id FROM unnest($1::int[]) f(row_limit) CROSS JOIN LATERAL (SELECT id FROM probe LIMIT row_limit) x;
SELECT x.id FROM unnest($1::int[]) f(row_limit) CROSS JOIN LATERAL (SELECT id FROM probe LIMIT f.row_limit::int + 1) x;
SELECT x.id FROM unnest($1::int[]) f(row_limit) CROSS JOIN LATERAL (SELECT id FROM probe LIMIT coalesce(f.row_limit, 1)) x;
SELECT x.id FROM unnest($1::int[]) f(row_limit) CROSS JOIN LATERAL (SELECT id FROM probe FETCH FIRST (f.row_limit) ROWS ONLY) x;
SELECT x.id FROM unnest($1::int[], $2::int[]) f(id, row_limit) CROSS JOIN LATERAL (SELECT id FROM probe LIMIT f.row_limit) x;
SELECT x.id FROM limits l, unnest(l.counts) f(row_limit) CROSS JOIN LATERAL (SELECT id FROM probe LIMIT f.row_limit) x;
SELECT x.id FROM unnest($1::int[]) f(row_limit) CROSS JOIN LATERAL (SELECT id FROM probe f LIMIT f.row_limit) x;
SELECT x.id FROM unnest($1::int[]) f(row_limit) CROSS JOIN (SELECT id FROM probe LIMIT f.row_limit) x;
SELECT x.id FROM unnest($1::int[]) f(row_limit) CROSS JOIN LATERAL (SELECT id FROM probe LIMIT unknown.row_limit) x;
SELECT x.id FROM unnest($1::int[]) f(row_limit) CROSS JOIN LATERAL (SELECT id FROM probe LIMIT f.row_limit + probe.id) x;
SELECT x.id FROM unnest($1::int[]) CROSS JOIN LATERAL (SELECT id FROM probe LIMIT row_limit) x;
SELECT x.id FROM unnest($1::int[]) f CROSS JOIN LATERAL (SELECT id FROM probe LIMIT f.row_limit) x;
SELECT x.id FROM LATERAL unnest($1::int[]) f(row_limit) CROSS JOIN LATERAL (SELECT id FROM probe LIMIT f.row_limit) x;
SELECT x.id FROM LATERAL generate_series(1, 2) f(row_limit) CROSS JOIN LATERAL (SELECT id FROM probe LIMIT f.row_limit) x;
SELECT x.id FROM LATERAL unnest(input => $1::int[]) f(row_limit) CROSS JOIN LATERAL (SELECT id FROM probe LIMIT f.row_limit) x;
SELECT x.id FROM unnest($1::int[]) f(row_limit) LEFT JOIN limits l ON true CROSS JOIN LATERAL (SELECT id FROM probe LIMIT f.row_limit) x;
SELECT x.id FROM unnest($1::int[]) f(row_limit) CROSS JOIN LATERAL ((SELECT id FROM probe) UNION ALL (SELECT id FROM probe) LIMIT f.row_limit) x;
SELECT x.id FROM (limits l JOIN limits r ON true) CROSS JOIN LATERAL (SELECT id FROM probe LIMIT row_limit) x;
SELECT x.id FROM unnest($1::int[]) f(row_limit) CROSS JOIN LATERAL (SELECT id FROM probe FETCH FIRST (f.row_limit) ROWS WITH TIES) x;
SELECT x.id FROM unnest($1::int[]) f(row_limit) CROSS JOIN LATERAL (SELECT 1 AS id LIMIT row_limit) x;
SELECT x.id FROM unnest($1::int[]) f(row_limit), limits l CROSS JOIN LATERAL (SELECT 1 AS id LIMIT row_limit) x;
SELECT x.id FROM limits f CROSS JOIN LATERAL (SELECT id FROM probe LIMIT f.row_limit) x;
SELECT x.id FROM unnest($1::int[]) f(row_limit) CROSS JOIN LATERAL (SELECT id FROM probe LIMIT coalesce(f.row_limit, probe.id)) x;
SELECT id FROM probe f LIMIT f.row_limit;
